#!/usr/bin/env node
// Generates the Dart mirror of the security-bearing constants in
// `contracts/src/bridge/http.ts` for the iOS/Flutter shell. `--check` verifies
// the generated file matches (CI/DoD mode); default rewrites it.
//
// Sibling of gen-bridge-swift.mjs rather than one script emitting both: the
// emitters are language-specific, each shell regenerates independently, and the
// DoD names the Swift script by path. The fragile half — extraction plus the
// refuse-to-emit guards — is shared in scripts/lib/bridge-http-contract.mjs, so
// there is exactly one place that reads the contract.
//
// The forbidden-header list and the origin-relative path rule are CONTRACT
// semantics, not per-shell choices: both shells enforce the same generated set.
import fs from "node:fs";
import path from "node:path";
import { camelCase, emit, readBridgeHttpContract, SOURCE_REL } from "./lib/bridge-http-contract.mjs";
import {
  APP_CONTRACT_SOURCE_REL,
  readBridgeDartContracts,
  STAGING_SOURCE_REL,
  STREAM_SOURCE_REL,
} from "./lib/bridge-dart-contract.mjs";

const ROOT = new URL("..", import.meta.url).pathname;
const OUT_REL = {
  path: "app/lib/gen/bridge_http_contract.g.dart",
  envVar: "OMI_IOS_SHELL_DIR",
};

// In-repo at core/shells/ios since the PR-6 promotion; see gen-bridge-swift.mjs.
const SHELL_DIR = process.env[OUT_REL.envVar] ?? path.join(ROOT, "shells/ios");

const check = process.argv.includes("--check");
const contractRoot = process.env.OMI_BRIDGE_DART_CONTRACT_ROOT
  ? new URL(`file://${path.resolve(process.env.OMI_BRIDGE_DART_CONTRACT_ROOT)}/scripts/lib/`)
  : new URL("./lib/", import.meta.url);

let contract;
let bridgeContracts;
try {
  const sourceRoot = process.env.OMI_BRIDGE_DART_CONTRACT_ROOT ?? ROOT;
  contract = readBridgeHttpContract(path.join(sourceRoot, SOURCE_REL));
  bridgeContracts = readBridgeDartContracts(contractRoot);
} catch (err) {
  console.error(`gen-bridge-dart: ${err.message}`);
  console.error(`  source: ${SOURCE_REL}`);
  process.exit(1);
}
const { channel, replyFunction, forbiddenHeaders, reasons, failureStatus } = contract;
const toShellMessages = [...bridgeContracts.toShell.keys()];
const fromShellMessages = [...bridgeContracts.fromShell.keys()];
if (toShellMessages.length !== 3 || fromShellMessages.length !== 3) {
  throw new Error("bridge stream contract no longer has exactly three messages in each direction");
}
const dartSet = (values) => `{${values.map((value) => `'${value}'`).join(", ")}}`;
const dartFieldMap = (variants) =>
  [...variants.entries()].map(([name, fields]) => `    '${name}': ${dartSet(fields)},`).join("\n");

const content =
  [
    `// GENERATED by core/scripts/gen-bridge-dart.mjs from ${SOURCE_REL},`,
    `// ${STREAM_SOURCE_REL}, ${STAGING_SOURCE_REL}, and ${APP_CONTRACT_SOURCE_REL}.`,
    "// Do not edit by hand. Run `node scripts/gen-bridge-dart.mjs` in core/",
    "// after changing those contracts;",
    "// `--check` fails on drift and runs as part of `pnpm verify`.",
    "",
    "/// BridgeHttpFailureReason — the only reasons a shell may report.",
    "enum BridgeHttpFailureReason {",
    ...reasons.map((r) => `  ${camelCase(r)}('${r}'),`),
    "  ;",
    "",
    "  const BridgeHttpFailureReason(this.wire);",
    "",
    "  /// The exact string the contract expects on the wire.",
    "  final String wire;",
    "",
    "  /// BRIDGE_HTTP_FAILURE_STATUS — the synthetic status the web binding maps",
    "  /// this reason onto, so `classifyStatus` stays the one place statuses",
    "  /// become taxonomy. Present for parity with the Swift mirror; the mapping",
    "  /// is applied by the web binding, not here.",
    "  int get syntheticStatus {",
    "    switch (this) {",
    ...reasons.flatMap((r) => [
      `      case BridgeHttpFailureReason.${camelCase(r)}:`,
      `        return ${failureStatus.get(r)};`,
    ]),
    "    }",
    "  }",
    "}",
    "",
    "class BridgeHttpContract {",
    "  const BridgeHttpContract._();",
    "",
    "  /// BRIDGE_HTTP_CHANNEL — the JavaScript channel name the surface",
    "  /// feature-detects. Must match the contract exactly or bridge mode is",
    "  /// silently unavailable and the surface falls back to its dev transport.",
    `  static const String channel = '${channel}';`,
    "",
    "  /// BRIDGE_HTTP_REPLY_FUNCTION — the global the surface installs for",
    "  /// one-way channels. A Flutter JavaScriptChannel cannot reply, so the",
    "  /// host delivers each reply by invoking this with (id, replyJson).",
    `  static const String replyFunction = '${replyFunction}';`,
    "",
    "  /// BRIDGE_HTTP_FORBIDDEN_HEADERS — stripped from caller headers,",
    "  /// case-insensitively, BEFORE the shell adds its own credential.",
    "  /// Enforced, never trusted: a compromised surface must not be able to",
    "  /// forge or override credentials.",
    "  static const Set<String> forbiddenHeaders = {",
    ...forbiddenHeaders.map((h) => `    '${h}',`),
    "  };",
    "}",
    "",
    "class BridgeStreamContract {",
    "  const BridgeStreamContract._();",
    `  static const String messageChannel = '${bridgeContracts.streamChannel}';`,
    `  static const String sinkFunction = '${bridgeContracts.streamSink}';`,
    `  static const String chatGenerationChannel = '${bridgeContracts.chatGenerationChannel}';`,
    `  static const String openMessage = '${toShellMessages[0]}';`,
    `  static const String grantMessage = '${toShellMessages[1]}';`,
    `  static const String cancelMessage = '${toShellMessages[2]}';`,
    `  static const String dataMessage = '${fromShellMessages[0]}';`,
    `  static const String endMessage = '${fromShellMessages[1]}';`,
    `  static const String errorMessage = '${fromShellMessages[2]}';`,
    `  static const Set<String> chatGenerationParameterFields = ${dartSet(bridgeContracts.chatGenerationParameterFields)};`,
    "  static const Map<String, Set<String>> toShellFields = {",
    dartFieldMap(bridgeContracts.toShell),
    "  };",
    "  static const Map<String, Set<String>> fromShellFields = {",
    dartFieldMap(bridgeContracts.fromShell),
    "  };",
    "}",
    "",
    "enum ChatAttachmentStagingFailureReason {",
    ...bridgeContracts.stagingFailureReasons.map((reason) => `  ${camelCase(reason)}('${reason}'),`),
    "  ;",
    "  const ChatAttachmentStagingFailureReason(this.wire);",
    "  final String wire;",
    "}",
    "",
    "class ChatAttachmentStagingContract {",
    "  const ChatAttachmentStagingContract._();",
    `  static const String channel = '${bridgeContracts.stagingChannel}';`,
    `  static const String replyFunction = '${bridgeContracts.stagingReply}';`,
    `  static const String requestMessage = '${bridgeContracts.stagingRequestMessage}';`,
    `  static const Set<String> requestFields = ${dartSet(bridgeContracts.stagingRequestFields)};`,
    `  static const Set<String> descriptorFields = ${dartSet(bridgeContracts.descriptorFields)};`,
    `  static const String stagedState = '${bridgeContracts.stagedState}';`,
    "}",
    "",
    "class AppRequestContract {",
    "  const AppRequestContract._();",
    `  static const String versionHeader = '${bridgeContracts.appContractHeader}';`,
    `  static const String version = '${bridgeContracts.appContractVersion}';`,
    "}",
    "",
  ].join("\n");

process.exit(
  emit({
    label: "bridge dart",
    shellDir: SHELL_DIR,
    outRel: OUT_REL,
    content,
    check,
    summary: `http=${channel}, stream=${bridgeContracts.streamChannel}, staging=${bridgeContracts.stagingChannel}`,
    fs,
    path,
  }),
);
